  &DefaultButton;




function filter$confirmpassword(p){
  this.constructor(p);
}
filter$confirmpassword.prototype = new DirEvent();
filter$confirmpassword.prototype.afterInit = function(){
  var p = this._dir;
  p.jObject('old_pass').attr('type', 'password');
  if ($.userinfo && $.userinfo.obj && $.userinfo.val("LocalCache") == "0") p.valForm('old_pass', '222222');
}
filter$confirmpassword.prototype.buttonDialogClick = function(id){
  var p = this._dir;
  if (id == 'filterOk') {
    this.checkNotBlank(function(m){
      $.login($.userinfo.val("username"), p.valForm('old_pass'), 5000, function(v){
        $.clearClientCache();
        if (p.options._reload) location.reload(false);
        else p._close();
      }, function(){
        p.jObject('old_pass').focus();
      }, true)
    });
  } else {
    DirEvent.prototype.buttonDialogClick.apply(this, arguments);
  }
}
